import type { IExecuteFunctions, INodeExecutionData } from "n8n-workflow";
import { NodeOperationError } from "n8n-workflow";
import { execa } from "execa";

/**
 * Action runner for 'qsv transpose'
 * Auto-generated by scripts/generate-qsv-nodes.ts
 */
export async function executeTranspose(
  this: IExecuteFunctions,
  itemIndex: number,
): Promise<INodeExecutionData[]> {
  const inputPath = this.getNodeParameter("inputPath", itemIndex, "") as string;
  if (!inputPath) {
    throw new NodeOperationError(
      this.getNode(),
      "Input CSV file path is required.",
      { itemIndex },
    );
  }

  const args: string[] = ["transpose"];

  // Collect options and flags
  try {
    const val = this.getNodeParameter("multipass", itemIndex, false) as boolean;
    if (val) {
      args.push("--multipass");
    }
  } catch {}

  try {
    const val = this.getNodeParameter("select", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--select", val);
    }
  } catch {}

  try {
    const val = this.getNodeParameter("long", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--long", val);
    }
  } catch {}

  try {
    const val = this.getNodeParameter("delimiter", itemIndex, "") as string;
    if (val !== undefined && val !== "") {
      args.push("--delimiter", val);
    }
  } catch {}

  try {
    const val = this.getNodeParameter("memcheck", itemIndex, false) as boolean;
    if (val) {
      args.push("--memcheck");
    }
  } catch {}

  try {
    const outputPath = this.getNodeParameter(
      "outputPath",
      itemIndex,
      "",
    ) as string;
    if (outputPath) {
      args.push("--output", outputPath);
    }
  } catch {}

  args.push(inputPath);

  try {
    const { stdout, stderr } = await execa("qsv", args);
    let resultJson: any;

    try {
      resultJson = JSON.parse(stdout);
    } catch {
      resultJson = {
        command: "qsv transpose",
        inputPath,
        rawOutput: stdout,
      };
    }

    return [
      {
        json: {
          success: true,
          command: "transpose",
          inputPath,
          result: resultJson,
        },
      },
    ];
  } catch (error: any) {
    throw new NodeOperationError(
      this.getNode(),
      `Failed executing 'qsv transpose': ${error.stderr || error.message}`,
      { itemIndex },
    );
  }
}
